-- Equipment persistence (roadmap row 3): owner-scoped bag and shot assignments.
-- Existing public RPC signatures remain available to older clients.
create table public.equipment (id uuid not null, owner_id uuid not null, data jsonb not null, primary key(owner_id,id));
create table public.equipment_assignments (shot_id uuid not null, owner_id uuid not null, equipment_id uuid not null, club_label text not null, primary key(owner_id,shot_id), foreign key(owner_id,shot_id) references public.shots(owner_id,id), foreign key(owner_id,equipment_id) references public.equipment(owner_id,id));
create index equipment_assignments_equipment on public.equipment_assignments(owner_id,equipment_id);
do $$ declare t text; begin foreach t in array array['equipment','equipment_assignments'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from public, anon, authenticated',t); execute format('grant select on public.%I to authenticated',t); execute format('create policy owner_read on public.%I for select to authenticated using ((select auth.uid()) = owner_id)',t); end loop; end $$;
create function private.valid_equipment(e jsonb) returns boolean language plpgsql immutable set search_path='' as $$ begin
 if not coalesce(jsonb_typeof(e)='object' and jsonb_typeof(e->'id')='string' and lower(e->>'id') ~ '^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$' and jsonb_typeof(e->'inrangeLabel')='string' and length(private.js_trim(e->>'inrangeLabel')) between 1 and 30 and e->>'status' in ('in-bag','retired') and jsonb_typeof(e->'name')='string' and length(private.js_trim(e->>'name')) between 1 and 200 and (e->'manufacturer'='null'::jsonb or (jsonb_typeof(e->'manufacturer')='string' and length(e->>'manufacturer')<=200)) and (e->'loft'='null'::jsonb or (jsonb_typeof(e->'loft')='string' and length(e->>'loft')<=30)) and (e->'acquiredOn'='null'::jsonb or ((e->>'acquiredOn') ~ '^\d{4}-\d{2}-\d{2}$' and to_char((e->>'acquiredOn')::date,'YYYY-MM-DD')=e->>'acquiredOn')) and (e->'retiredOn'='null'::jsonb or ((e->>'retiredOn') ~ '^\d{4}-\d{2}-\d{2}$' and to_char((e->>'retiredOn')::date,'YYYY-MM-DD')=e->>'retiredOn')) and jsonb_typeof(e->'revision')='number' and (e->>'revision') ~ '^[0-9]+$' and (e->>'revision')::integer>=0,false) then return false; end if;
 return true; exception when others then return false; end $$;
-- save_equipment: revision null creates with revision 0; an integer revision must match the stored one and is bumped by one. One dataset bump per successful write.
create function private.save_equipment(p_equipment jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=private.lock_owner(); existing public.equipment%rowtype; saved jsonb; begin
 if not coalesce(jsonb_typeof(p_equipment)='object' and jsonb_typeof(p_equipment->'id')='string' and (p_equipment->>'id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$',false) then raise exception 'Invalid equipment'; end if;
 if p_equipment->'revision'='null'::jsonb then
  if not private.valid_equipment(jsonb_set(p_equipment,'{revision}','0'::jsonb)) then raise exception 'Invalid equipment'; end if;
  if exists(select 1 from public.equipment where owner_id=u and id=(p_equipment->>'id')::uuid) then raise exception 'Equipment conflict'; end if;
  saved:=p_equipment || jsonb_build_object('id',(p_equipment->>'id')::uuid,'revision',0);
  insert into public.equipment values((p_equipment->>'id')::uuid,u,saved);
 elsif (p_equipment->>'revision') ~ '^[0-9]+$' and private.valid_equipment(p_equipment) then
  select * into existing from public.equipment where owner_id=u and id=(p_equipment->>'id')::uuid for update;
  if not found or existing.data->>'revision'<>p_equipment->>'revision' then raise exception 'Equipment conflict'; end if;
  if (p_equipment->>'revision')::integer=2147483647 then raise exception 'Equipment revision limit reached'; end if;
  saved:=p_equipment || jsonb_build_object('id',existing.id,'revision',(p_equipment->>'revision')::integer+1);
  update public.equipment set data=saved where owner_id=u and id=existing.id;
 else raise exception 'Invalid equipment'; end if;
 perform private.bump(u);
 return saved;
end $$;
-- assign_equipment: confirms a previewed group atomically. equipmentId null clears the listed shots. The club label is pinned at confirmation so later corrections stay repairable.
create function private.assign_equipment(p_preview jsonb) returns void language plpgsql security definer set search_path='' as $$ declare u uuid:=private.lock_owner(); sid uuid; eid uuid; label text; s text; shot uuid; eff text; v bigint; begin
 if not coalesce(jsonb_typeof(p_preview)='object' and jsonb_typeof(p_preview->'expectedVersion')='number' and (p_preview->>'expectedVersion') ~ '^[0-9]+$' and jsonb_typeof(p_preview->'sessionId')='string' and (p_preview->>'sessionId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' and jsonb_typeof(p_preview->'clubLabel')='string' and length(private.js_trim(p_preview->>'clubLabel')) between 1 and 30 and (p_preview->'equipmentId'='null'::jsonb or (jsonb_typeof(p_preview->'equipmentId')='string' and (p_preview->>'equipmentId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')) and jsonb_typeof(p_preview->'shotIds')='array' and jsonb_array_length(p_preview->'shotIds') between 1 and 20000,false) then raise exception 'Invalid assignment preview'; end if;
 sid:=(p_preview->>'sessionId')::uuid; label:=private.js_trim(p_preview->>'clubLabel');
 if exists(select 1 from jsonb_array_elements(p_preview->'shotIds') x where jsonb_typeof(x)<>'string' or (x#>>'{}') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')  then raise exception 'Invalid shot IDs'; end if;
 if (select count(distinct t::uuid) from jsonb_array_elements_text(p_preview->'shotIds') t)<>jsonb_array_length(p_preview->'shotIds') then raise exception 'Invalid shot IDs'; end if;
 v:=(select version from private.versions where owner_id=u);
 if v<>(p_preview->>'expectedVersion')::bigint then raise exception 'Assignment preview conflict'; end if;
 if not exists(select 1 from public.sessions where owner_id=u and id=sid) then raise exception 'Unknown session'; end if;
 if p_preview->'equipmentId' is distinct from 'null'::jsonb then
  eid:=(p_preview->>'equipmentId')::uuid;
  if not exists(select 1 from public.equipment where owner_id=u and id=eid and private.js_trim(data->>'inrangeLabel')=private.js_trim(label)) then raise exception 'Equipment label conflict'; end if;
 end if;
 for s in select t from jsonb_array_elements_text(p_preview->'shotIds') t loop
  shot:=s::uuid;
  select case when r.state->'club'->>'kind'='corrected' then r.state->'club'->>'club' else sh.payload->>'recordedClub' end into eff from public.shots sh join public.reviews r on r.owner_id=sh.owner_id and r.shot_id=sh.id where sh.owner_id=u and sh.id=shot and sh.session_id=sid;
  if not found then raise exception 'Shot not in this session'; end if;
  if private.js_trim(eff) is distinct from label then raise exception 'Assignment club label conflict'; end if;
 end loop;
 if p_preview->'equipmentId' is distinct from 'null'::jsonb then
  for s in select t from jsonb_array_elements_text(p_preview->'shotIds') t loop
   insert into public.equipment_assignments(shot_id,owner_id,equipment_id,club_label) values(s::uuid,u,eid,label) on conflict (owner_id,shot_id) do update set equipment_id=excluded.equipment_id,club_label=excluded.club_label;
  end loop;
 else
  delete from public.equipment_assignments where owner_id=u and shot_id in (select t::uuid from jsonb_array_elements_text(p_preview->'shotIds') t);
 end if;
 perform private.bump(u);
end $$;
-- Page the new collections inside the version-checked snapshot, deterministically ordered.
create or replace function private.dataset_page(p_table text,p_offset integer,p_limit integer) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare u uuid:=private.owner(); result jsonb; begin if p_offset is null or p_limit is null or p_offset<0 or p_limit not between 1 and 1000 then raise exception 'Invalid page'; end if; case p_table when 'sessions' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,data from public.sessions where owner_id=u order by id offset p_offset limit p_limit) x; when 'shots' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select s.id,s.payload || jsonb_build_object('id',s.id,'sessionId',s.session_id,'review',r.state,'revision',r.revision) data from public.shots s join public.reviews r on r.shot_id=s.id and r.owner_id=s.owner_id where s.owner_id=u order by s.id offset p_offset limit p_limit) x; when 'imports' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,jsonb_build_object('id',id,'sessionId',session_id,'originalBase64',replace(encode(original,'base64'),E'\n',''),'fileHash',file_hash,'contentHash',content_hash,'parserVersion',parser_version) data from public.imports where owner_id=u order by id offset p_offset limit p_limit) x; when 'events' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,jsonb_build_object('id',id,'shotId',shot_id,'before',before_state,'after',after_state,'createdAt',created_at,'undone',undone) data from public.review_events where owner_id=u order by id offset p_offset limit p_limit) x; when 'equipment' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,data from public.equipment where owner_id=u order by id offset p_offset limit p_limit) x; when 'equipmentAssignments' then select coalesce(jsonb_agg(x.data order by x.shot_id),'[]') into result from (select shot_id,jsonb_build_object('shotId',shot_id,'equipmentId',equipment_id,'clubLabel',club_label) data from public.equipment_assignments where owner_id=u order by shot_id offset p_offset limit p_limit) x; else raise exception 'Invalid dataset table'; end case; return result; end $$;
-- Restore accepts legacy datasets without equipment arrays (v1: empty collections) and full v2 datasets. Equipment counts toward the empty-account check; mismatched assignments are preserved for review.
create or replace function private.restore_backup(p_dataset jsonb) returns void language plpgsql security definer set search_path='' as $$ declare u uuid:=private.lock_owner(); x jsonb; b bytea; sid uuid; shot uuid; imp public.imports%rowtype; canonical jsonb; shot_count integer; begin
 if exists(select 1 from public.sessions where owner_id=u) or exists(select 1 from public.shots where owner_id=u) or exists(select 1 from public.equipment where owner_id=u) or exists(select 1 from public.equipment_assignments where owner_id=u) then raise exception 'Restore requires empty dataset'; end if;
 if not coalesce(jsonb_typeof(p_dataset)='object' and (p_dataset->>'version') ~ '^[0-9]+$' and jsonb_typeof(p_dataset->'sessions')='array' and jsonb_typeof(p_dataset->'shots')='array' and jsonb_typeof(p_dataset->'imports')='array' and jsonb_typeof(p_dataset->'events')='array' and jsonb_array_length(p_dataset->'sessions')<=20000 and jsonb_array_length(p_dataset->'shots')<=100000 and jsonb_array_length(p_dataset->'imports')<=20000 and jsonb_array_length(p_dataset->'events')<=200000 and (p_dataset ? 'equipment') = (p_dataset ? 'equipmentAssignments') and (not (p_dataset ? 'equipment') or (jsonb_typeof(p_dataset->'equipment')='array' and jsonb_array_length(p_dataset->'equipment')<=10000)) and (not (p_dataset ? 'equipmentAssignments') or (jsonb_typeof(p_dataset->'equipmentAssignments')='array' and jsonb_array_length(p_dataset->'equipmentAssignments')<=200000)),false) then raise exception 'Invalid backup'; end if;
 for x in select value from jsonb_array_elements(p_dataset->'sessions') loop if not private.valid_session(x) then raise exception 'Invalid backup session'; end if; insert into public.sessions values((x->>'id')::uuid,u,x); end loop;
 for x in select value from jsonb_array_elements(p_dataset->'imports') loop sid:=(x->>'sessionId')::uuid; if not exists(select 1 from public.sessions where id=sid and owner_id=u) or not coalesce(jsonb_typeof(x->'originalBase64')='string' and jsonb_typeof(x->'fileHash')='string' and (x->>'fileHash') ~ '^[0-9a-f]{64}$' and jsonb_typeof(x->'contentHash')='string' and (x->>'contentHash') ~ '^[0-9a-f]{64}$' and jsonb_typeof(x->'parserVersion')='string',false) then raise exception 'Invalid backup import'; end if; b:=decode(x->>'originalBase64','base64'); if octet_length(b)>5242880 or encode(extensions.digest(b,'sha256'),'hex')<>x->>'fileHash' then raise exception 'Invalid backup bytes'; end if; insert into public.imports values((x->>'id')::uuid,u,sid,b,x->>'fileHash',x->>'contentHash',x->>'parserVersion'); end loop;
 for x in select value from jsonb_array_elements(p_dataset->'shots') loop sid:=(x->>'sessionId')::uuid; shot:=(x->>'id')::uuid; if not exists(select 1 from public.sessions where id=sid and owner_id=u) or not private.valid_shot(x) or not private.valid_review(x->'review') or (x->>'revision') !~ '^[0-9]+$' then raise exception 'Invalid backup shot'; end if; insert into public.shots values(shot,u,sid,x-'id'-'sessionId'-'review'-'revision'); insert into public.reviews values(shot,u,x->'review',(x->>'revision')::integer); end loop;
 if p_dataset ? 'equipment' then
  if (select count(*) from jsonb_array_elements(p_dataset->'equipment'))<>(select count(distinct value->>'id') from jsonb_array_elements(p_dataset->'equipment')) then raise exception 'Invalid backup equipment'; end if;
  for x in select value from jsonb_array_elements(p_dataset->'equipment') loop if not private.valid_equipment(x) then raise exception 'Invalid backup equipment'; end if; insert into public.equipment values((x->>'id')::uuid,u,jsonb_set(x,'{id}',to_jsonb((x->>'id')::uuid))); end loop;
 end if;
 if p_dataset ? 'equipmentAssignments' then
  if (select count(*) from jsonb_array_elements(p_dataset->'equipmentAssignments'))<>(select count(distinct value->>'shotId') from jsonb_array_elements(p_dataset->'equipmentAssignments')) then raise exception 'Invalid backup assignment'; end if;
  for x in select value from jsonb_array_elements(p_dataset->'equipmentAssignments') loop
   if not coalesce(jsonb_typeof(x)='object' and jsonb_typeof(x->'shotId')='string' and (x->>'shotId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' and jsonb_typeof(x->'equipmentId')='string' and (x->>'equipmentId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' and jsonb_typeof(x->'clubLabel')='string' and length(private.js_trim(x->>'clubLabel')) between 1 and 30,false) then raise exception 'Invalid backup assignment'; end if;
   shot:=(x->>'shotId')::uuid;
   if not exists(select 1 from public.shots where owner_id=u and id=shot) or not exists(select 1 from public.equipment where owner_id=u and id=(x->>'equipmentId')::uuid) then raise exception 'Invalid backup assignment'; end if;
   insert into public.equipment_assignments values(shot,u,(x->>'equipmentId')::uuid,x->>'clubLabel');
  end loop;
 end if;
 for imp in select * from public.imports where owner_id=u loop
 select count(*),jsonb_build_object('headers',(select jsonb_agg(k) from jsonb_object_keys((select payload->'raw' from public.shots where owner_id=u and session_id=imp.session_id order by (payload->>'rowIndex')::integer limit 1)) k),'shots',jsonb_agg(payload order by (payload->>'rowIndex')::integer)) into shot_count,canonical from public.shots where owner_id=u and session_id=imp.session_id;
 if shot_count=0 or shot_count>20000 or exists(select 1 from (select (payload->>'rowIndex')::integer as n,row_number() over(order by (payload->>'rowIndex')::integer) as expected from public.shots where owner_id=u and session_id=imp.session_id) rows where n<>expected) or private.canonical_hash(canonical)<>imp.content_hash then raise exception 'Invalid backup content'; end if; perform private.validate_source(imp.original,canonical,imp.parser_version);
 end loop;
 for x in select value from jsonb_array_elements(p_dataset->'events') loop shot:=(x->>'shotId')::uuid; if not exists(select 1 from public.shots where id=shot and owner_id=u) or not private.valid_review(x->'before') or not private.valid_review(x->'after') then raise exception 'Invalid backup event'; end if; insert into public.review_events(id,owner_id,shot_id,before_state,after_state,created_at,undone) values((x->>'id')::uuid,u,shot,x->'before',x->'after',(x->>'createdAt')::timestamptz,coalesce((x->>'undone')::boolean,false)); end loop;
 if exists(select 1 from public.sessions s where owner_id=u and not exists(select 1 from public.imports i where i.session_id=s.id and i.owner_id=u)) then raise exception 'Session missing import'; end if; perform private.bump(u); end $$;
revoke all on function private.valid_equipment(jsonb),private.save_equipment(jsonb),private.assign_equipment(jsonb) from public, anon, authenticated;
grant execute on function private.save_equipment(jsonb),private.assign_equipment(jsonb) to authenticated;
create function public.save_equipment(p_equipment jsonb) returns jsonb language sql security invoker set search_path='' as $$ select private.save_equipment(p_equipment) $$;
create function public.assign_equipment(p_preview jsonb) returns void language sql security invoker set search_path='' as $$ select private.assign_equipment(p_preview) $$;
revoke all on function public.save_equipment(jsonb),public.assign_equipment(jsonb) from public, anon;
grant execute on function public.save_equipment(jsonb),public.assign_equipment(jsonb) to authenticated;
